{
  "name": "Pfeiffer TPG36x 真空规控制器",
  "name_en": "Pfeiffer TPG36x Vacuum Gauge Controller",
  "manufacturer": "Pfeiffer",
  "description": "用于连接和管理一到两个真空规通道的真空规控制器，可读取压力并配置仪器的单位、语言及以太网参数，常用于真空系统中的压力监测与真空状态读出。",
  "description_en": "A vacuum gauge controller for connecting and managing one or two vacuum gauge channels. It reads pressure and allows configuration of instrument units, language, and Ethernet settings, and is commonly used for pressure monitoring and vacuum-state readout in vacuum systems.",
  "actions": [
    {
      "action_name": "auto-ethernet_configuration",
      "description": "获取/设置以太网配置。",
      "description_en": "Get/set the Ethernet configuration."
    },
    {
      "action_name": "auto-language",
      "description": "获取/设置仪器语言。",
      "description_en": "Get/set the instrument language."
    },
    {
      "action_name": "auto-number_channels",
      "description": "获取/设置通道数量。",
      "description_en": "Get/set the number of channels."
    },
    {
      "action_name": "auto-query",
      "description": "发送底层查询命令并返回仪器响应。",
      "description_en": "Send a low-level query command and return the instrument response."
    },
    {
      "action_name": "auto-unit",
      "description": "获取/设置压力单位。",
      "description_en": "Get/set the pressure unit."
    },
    {
      "action_name": "auto-channel",
      "description": "获取指定通道对象。",
      "description_en": "Get a specific channel object."
    },
    {
      "action_name": "auto-mac_address",
      "description": "获取 MAC 地址。",
      "description_en": "Get the MAC address."
    },
    {
      "action_name": "auto-name",
      "description": "获取设备名称。",
      "description_en": "Get the device name."
    },
    {
      "action_name": "auto-pressure",
      "description": "获取第一通道测得的压力。",
      "description_en": "Get the pressure measured by the first channel."
    },
    {
      "action_name": "auto-status",
      "description": "获取仪器状态。",
      "description_en": "Get the instrument status."
    }
  ],
  "tag_hints": [
    "vacuum gauge controller",
    "vacuum pressure measurement",
    "Pfeiffer TPG361",
    "Pfeiffer TPG362",
    "multi-channel gauge readout",
    "serial communication",
    "Ethernet configuration"
  ]
}

